import { useState } from 'react';
import { Button, CommandDialog, CommandItem, CommandSection, useCommandShortcut } from '@strata/react';

export function Search() {
  const [isOpen, setOpen] = useState(false);
  useCommandShortcut(() => setOpen(true));
  return (
    <>
      <Button variant="outline" onPress={() => setOpen(true)}>Search…</Button>
      <CommandDialog isOpen={isOpen} onOpenChange={setOpen} placeholder="Search docs…" onAction={(key) => navigate(`/components/${key}`)}>
        <CommandSection title="Components">
          <CommandItem id="button">Button</CommandItem>
          <CommandItem id="dialog" textValue="Dialog modal">Dialog</CommandItem>
        </CommandSection>
      </CommandDialog>
    </>
  );
}
